const calendar=[
['Core basics','Light full-body','Core + stability','Erholung','Core + cardio','Light full-body','Erholung'],
['Core basics','Abs + cardio','Light full-body','Erholung','Core + cardio','Full-body mix','Erholung'],
['Core stability','Abs + cardio','Light full-body','Erholung','Core + cardio','Full-body mix','Erholung'],
['Core basics','Full-body mix','Core + stability','Erholung','Core + cardio','Full-body mix','Abschlussvorbereitung'],
['Core basics','Core + cardio','Light full-body','Erholung','Core + cardio','Full-body mix','Erholung']
];
function focusPool(focus,level){let pool=exercises.filter(e=>e.focus==='core'||e.focus==='full'||e.focus==='cardio');if(level==='Anfänger')pool=pool.filter(e=>e.low);if(focus==='Core')pool=pool.filter(e=>e.focus==='core');if(focus==='Cardio + Core')pool=pool.filter(e=>e.focus==='core'||e.focus==='cardio');return pool}
function shuffled(arr){let a=[...arr];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function makePlan({duration=20,pause=15,level='Anfänger',focus='Core + Ganzkörper',warmup=2,cooldown=3,challenge=false,day=1}={}){
 let total=duration*60,w=warmup*60,c=cooldown*60,main=total-w-c;if(main<60)throw Error('Für Aufwärmen, Hauptteil und Cool-down bleibt zu wenig Zeit. Bitte Dauer oder Aufwärm-/Cool-down-Zeit anpassen.');
 let target=level==='Anfänger'?35:level==='Fortgeschritten'?40:45;
 let pool=focusPool(focus,level);if(pool.length<4&&focus!=='Core')pool=focusPool('Core + Ganzkörper',level);pool=shuffled(pool);
 // Count is derived from the actual main-part seconds and chosen rest duration.
 // A 36-minute workout with 2 min warm-up, 3 min cool-down and 15 s rests now produces ~38 exercises.
 let n=Math.max(2,Math.min(60,Math.round((main+pause)/(target+pause))));
 while(n>2&&main-(n-1)*pause<n*12)n--;
 let active=main-(n-1)*pause;if(active<=0)throw Error('Mit dieser Pausenlänge ist kein sinnvoller Hauptteil möglich.');
 let base=Math.floor(active/n),rem=active%n;let durations=Array.from({length:n},(_,i)=>base+(i<rem?1:0));
 let chosen=[];let lastFocus='';for(let i=0;i<n;i++){let roundStart=Math.floor(i/pool.length)*pool.length;let usedIds=chosen.slice(roundStart).map(x=>x.id);let candidates=pool.filter(e=>!usedIds.includes(e.id));if(!candidates.length)candidates=[...pool];let best=candidates.find(e=>e.focus!==lastFocus)||candidates[0];chosen.push(best);lastFocus=best.focus;}
 // Challenge days use a day-specific emphasis while keeping recovery days genuinely light.
 const routine=challenge?getChallengeRoutine(day,level):null;
 if(routine?.rest){chosen=Array.from({length:Math.max(3,Math.min(6,Math.floor(main/((target+pause)))) )},(_,i)=>exercises.find(e=>e.id===['march','sidestep','coolwalk','stretchside','backmob','arms'][i%6])).filter(Boolean);n=chosen.length;active=main-(n-1)*pause;durations=Array.from({length:n},(_,i)=>Math.floor(active/n)+(i<active%n?1:0));}
 const warmIds=['boxing-march','march','arms','sidestep','kneelift'];const coolIds=['stretchside','hipstretch','backmob','child-pose','cat-cow'];
 function phase(ids,seconds,minCount,maxCount,kind){let count=Math.max(minCount,Math.min(maxCount,Math.round(seconds/45)));count=Math.min(count,ids.length);let base=Math.floor(seconds/count),r=seconds%count;return ids.slice(0,count).map((id,i)=>({...exercises.find(e=>e.id===id),seconds:base+(i<r?1:0),phase:kind}));}
 // Für Core maximal zwei kurze Warm-up-Übungen, anschließend ausschließlich Core und zum Abschluss 3–4 Dehn-/Mobilitätsübungen.
 const warmCount=Math.min(2,Math.max(1,Math.round(w/60)));
 const warm=phase(warmIds,w,warmCount,warmCount,'warm');
 const coolCount=Math.min(4,Math.max(3,Math.round(c/60)+2));
 const cool=phase(coolIds,c,coolCount,coolCount,'cool');
 // Seitenübungen werden als vollständiges Paar eingeplant. Wird eine Seite gewählt,
 // ergänzen wir die Gegenseite direkt daneben und verteilen die aktive Zeit neu.
 const sidePairs=[['side-leg-raise-left','side-leg-raise-right'],['kneeling-side-plank-left','kneeling-side-plank-right']];
 for(const pair of sidePairs){
   const leftEx=exercises.find(e=>e.id===pair[0]), rightEx=exercises.find(e=>e.id===pair[1]);
   const left=chosen.findIndex(e=>e.id===pair[0]), right=chosen.findIndex(e=>e.id===pair[1]);
   if(left>=0 && right<0 && rightEx) chosen.splice(left+1,0,rightEx);
   else if(right>=0 && left<0 && leftEx) chosen.splice(right,0,leftEx);
   let li=chosen.findIndex(e=>e.id===pair[0]), ri=chosen.findIndex(e=>e.id===pair[1]);
   if(li>=0&&ri>=0&&ri!==li+1){const [r]=chosen.splice(ri,1);li=chosen.findIndex(e=>e.id===pair[0]);chosen.splice(li+1,0,r);}
 }
 n=chosen.length;active=main-(n-1)*pause;
 if(active<n*8) { active=n*8; }
 let pairBase=Math.floor(active/n),pairRem=active%n;
 durations=Array.from({length:n},(_,i)=>pairBase+(i<pairRem?1:0));
 const mainItems=chosen.map((e,i)=>({...e,seconds:durations[i],phase:'main'}));
 const items=[...warm];mainItems.forEach((e,i)=>{items.push(e);if(i<mainItems.length-1&&pause>0)items.push({id:'rest-'+i,name:'Pause',focus:'rest',emoji:'⏸️',inst:'Atme ruhig und bereite dich auf die nächste Übung vor.',seconds:pause,phase:'rest'});});items.push(...cool);
 // Countdown is overlaid on the final seconds of an existing pause or warmup, never adds time.
 return {duration,pause,level,focus,warmup,cooldown,items,totalSeconds:items.reduce((s,e)=>s+e.seconds,0),challenge,day};
}
function getChallengeRoutine(day,level){const d=((day-1)%30)+1;const restDays=level==='Anfänger'?[4,7,10,14,18,21,24,28]:level==='Fortgeschritten'?[7,12,16,20,24,28]:[5,10,15,20,24,28];return {rest:restDays.includes(d),focus:d%3===0?'Core + Ganzkörper':d%3===1?'Core':'Cardio + Core'};}
function bottomNav(active='home'){return `<nav class="navbottom"><button class="${active==='home'?'active':''}" data-go="home">Training</button><button class="${active==='exercises'?'active':''}" data-go="exercises">Übungen</button><button class="${active==='history'?'active':''}" data-go="history">Statistik</button><button class="${active==='generator'?'active':''}" data-go="generator">Plan</button><button class="${active==='profile'?'active':''}" data-go="profile">Mein Profil</button></nav>`}
